-- БЛОК 5: МЕНЕДЖЕР ПОСТ-ЭФФЕКТОВ LIGHTING (VFX ENGINE)
-- ══════════════════════════════════════════════════════════════════════════════
local VFX = {}
local GUI = env.GUI
local OwnedLighting = {}
local SuppressedLighting = {}

function VFX.SyncEnvironment()
    local function suppressed(obj)
        return (obj:IsA('Sky') and Lighting:FindFirstChild('Visuals_Sky') ~= nil)
            or (obj:IsA('Atmosphere') and (Lighting:FindFirstChild('Visuals_Atmosphere') ~= nil or Lighting:FindFirstChild('Visuals_ClearAtmo') ~= nil))
            or (obj:IsA('PostEffect') and State.ActiveShader ~= nil)
    end
    for _,obj in ipairs(Lighting:GetChildren()) do
        if not OwnedLighting[obj] and suppressed(obj) and not SuppressedLighting[obj] then
            SuppressedLighting[obj]={Parent=obj.Parent,Enabled=obj:IsA('PostEffect') and obj.Enabled}
            if obj:IsA('PostEffect') then obj.Enabled=false else obj.Parent=nil end
        end
    end
    for obj,record in pairs(SuppressedLighting) do
        if not suppressed(obj) then
            pcall(function()
                if obj:IsA('PostEffect') then obj.Enabled=record.Enabled else obj.Parent=record.Parent end
            end)
            SuppressedLighting[obj]=nil
        end
    end
end

function VFX.RemoveSky()
    local sky=Lighting:FindFirstChild('Visuals_Sky')
    if sky and OwnedLighting[sky] then sky:Destroy(); OwnedLighting[sky]=nil end
    VFX.SyncEnvironment()
end

function VFX.GetOrCreate(className, name)
    local inst = Lighting:FindFirstChild(name)
    if not inst or not inst:IsA(className) then
        if inst then inst:Destroy() end
        inst = Instance.new(className)
        inst.Name = name
        OwnedLighting[inst] = true
        inst:SetAttribute('VisualsStandaloneOwned',true)
        inst.Destroying:Connect(function() OwnedLighting[inst]=nil end)
        inst.Parent = Lighting
    end
    if className == 'Atmosphere' then VFX.SyncEnvironment() end
    return inst
end

function VFX.GetBloom()       return VFX.GetOrCreate("BloomEffect", "Visuals_Bloom") end
function VFX.GetBlur()        return VFX.GetOrCreate("BlurEffect", "Visuals_Blur") end
function VFX.GetCC()          return VFX.GetOrCreate("ColorCorrectionEffect", "Visuals_CC") end
function VFX.GetSunRays()     return VFX.GetOrCreate("SunRaysEffect", "Visuals_SunRays") end
function VFX.GetDoF()         return VFX.GetOrCreate("DepthOfFieldEffect", "Visuals_DoF") end
function VFX.GetAtmosphere()  return VFX.GetOrCreate("Atmosphere", "Visuals_Atmosphere") end
function VFX.GetSky()
    local sky=VFX.GetOrCreate('Sky','Visuals_Sky')
    VFX.SyncEnvironment()
    return sky
end

local WindLinesFolder = nil
local WindLinesConn = nil
local GroundFogPart, GroundFogConnection

function VFX.UpdateGroundFog(enabled)
    if GroundFogConnection then GroundFogConnection:Disconnect(); GroundFogConnection=nil end
    if GroundFogPart then GroundFogPart:Destroy(); GroundFogPart=nil end
    if not enabled or State.Unloaded then return end
    local part=Instance.new('Part')
    part.Name='Visuals_GroundFog'
    part:SetAttribute('StandaloneVFX_Owner','GroundFog')
    part.Anchored=true
    part.Transparency=1
    part.CanCollide=false
    part.CanTouch=false
    part.CanQuery=false
    part.CastShadow=false
    part.Size=Vector3.new(65,0.1,65)
    local emitter=Instance.new('ParticleEmitter')
    emitter:SetAttribute('StandaloneVFX_Owner','GroundFog')
    emitter.Texture='rbxasset://textures/particles/smoke_main.dds'
    emitter.Color=ColorSequence.new(Color3.fromRGB(195,205,210))
    emitter.Size=NumberSequence.new(18)
    emitter.Transparency=NumberSequence.new({NumberSequenceKeypoint.new(0,1),NumberSequenceKeypoint.new(0.3,0.88),NumberSequenceKeypoint.new(0.7,0.88),NumberSequenceKeypoint.new(1,1)})
    emitter.Lifetime=NumberRange.new(5,7)
    emitter.Rate=15
    emitter.Speed=NumberRange.new(0.05,0.1)
    emitter.Rotation=NumberRange.new(0,360)
    emitter.RotSpeed=NumberRange.new(-4,4)
    emitter.LightInfluence=0.5
    emitter.Parent=part
    local function update()
        local char=LocalPlayer.Character
        local root=char and char:FindFirstChild('HumanoidRootPart')
        local humanoid=char and char:FindFirstChildOfClass('Humanoid')
        emitter.Enabled=root~=nil
        if root then
            local hip=humanoid and humanoid.HipHeight or 2
            if humanoid and humanoid.RigType==Enum.HumanoidRigType.R6 then hip=2 end
            part.CFrame=CFrame.new(root.Position-Vector3.new(0,hip+root.Size.Y/2-0.2,0))
        end
    end
    update()
    part.Parent=workspace
    GroundFogPart=part
    GroundFogConnection=RunService.Heartbeat:Connect(update)
end

function VFX.UpdateWindLines(on)
    if not on then
        if WindLinesConn then
            pcall(function() WindLinesConn:Disconnect() end)
            WindLinesConn = nil
        end
        if WindLinesFolder then
            pcall(function() WindLinesFolder:Destroy() end)
            WindLinesFolder = nil
        end
        return
    end

    if WindLinesFolder then return end
    local cam = workspace.CurrentCamera
    if not cam then return end

    WindLinesFolder = Instance.new("Folder")
    WindLinesFolder.Name = "Standalone_WindLines"
    WindLinesFolder.Parent = cam

    local windPart = Instance.new("Part")
    windPart.Name = "WindEmitterPart"
    windPart.Transparency = 1
    windPart.CanCollide = false
    windPart.CanQuery = false
    windPart.CanTouch = false
    windPart.Anchored = true
    windPart.Size = Vector3.new(40, 30, 10)
    windPart.Parent = WindLinesFolder

    local pe = Instance.new("ParticleEmitter")
    pe.Name = "WindStreak"
    pe.Texture = "rbxasset://textures/particles/smoke_main.dds"
    pe.Lifetime = NumberRange.new(0.5, 1.0)
    pe.Rate = 22
    pe.Speed = NumberRange.new(50, 90)
    pe.SpreadAngle = Vector2.new(5, 5)
    pe.EmissionDirection = Enum.NormalId.Right
    pe.Size = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.1),
        NumberSequenceKeypoint.new(0.5, 0.35),
        NumberSequenceKeypoint.new(1, 0.05),
    })
    pe.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.2, 0.35),
        NumberSequenceKeypoint.new(0.8, 0.45),
        NumberSequenceKeypoint.new(1, 1),
    })
    pe.Color = ColorSequence.new(Color3.fromRGB(220, 230, 245))
    pe.LightEmission = 0.2
    pe.Parent = windPart

    WindLinesConn = RunService.RenderStepped:Connect(function()
        local currentCam = workspace.CurrentCamera
        if currentCam and windPart.Parent then
            WindLinesFolder.Parent = currentCam
            windPart.CFrame = currentCam.CFrame * CFrame.new(-25, 0, -15)
        else
            VFX.UpdateWindLines(false)
        end
    end)
    TrackConnection(WindLinesConn)
end

function VFX.DisableAllFX()
    for _, name in ipairs({
        "Visuals_Bloom", "Visuals_Blur", "Visuals_CC", "Visuals_SunRays", "Visuals_DoF"
    }) do
        local inst = Lighting:FindFirstChild(name)
        if inst and inst:IsA("PostEffect") then inst.Enabled = false end
    end
    local atmo = Lighting:FindFirstChild("Visuals_Atmosphere")
    if atmo then atmo:Destroy() end
    VFX.UpdateWindLines(false)
    VFX.UpdateGroundFog(false)
    if State.ClearAtmosphere.Enabled then
        VFX.ApplyClearAtmosphere()
    end
end

function VFX.RestoreDefaultLighting()
    State.ActiveShader=nil
    VFX.DisableAllFX()
    for prop,val in pairs(DefaultLighting) do pcall(function() Lighting[prop]=val end) end
    if State.ActiveSky then VFX.ApplySky(State.ActiveSky) else VFX.RemoveSky() end
    VFX.SyncEnvironment()
end

