local AuraObjects = {}

local function resolveCharPart(char, name)
    local direct = char:FindFirstChild(name)
    if direct and direct:IsA('BasePart') then return direct end
    local aliases = {
        Torso={'UpperTorso','LowerTorso'}, UpperTorso={'Torso'}, LowerTorso={'Torso'},
        ['Left Arm']={'LeftUpperArm','LeftHand'}, ['Right Arm']={'RightUpperArm','RightHand'},
        ['Left Leg']={'LeftLowerLeg','LeftFoot'}, ['Right Leg']={'RightLowerLeg','RightFoot'},
        LeftUpperArm={'Left Arm'}, RightUpperArm={'Right Arm'},
        LeftLowerArm={'Left Arm'}, RightLowerArm={'Right Arm'},
        LeftHand={'Left Arm'}, RightHand={'Right Arm'},
        LeftUpperLeg={'Left Leg'}, RightUpperLeg={'Right Leg'},
        LeftLowerLeg={'Left Leg'}, RightLowerLeg={'Right Leg'},
        LeftFoot={'Left Leg'}, RightFoot={'Right Leg'},
    }
    for _,alias in ipairs(aliases[name] or {}) do
        local part=char:FindFirstChild(alias)
        if part and part:IsA('BasePart') then return part end
    end
    return nil
end

local function decodeAuraValue(value, objects)
    if type(value)~='table' then return value end
    local t,v=value.t,value.v
    if t=='Ref' then return assert(objects[v], 'Missing aura reference '..tostring(v)) end
    if t=='Enum' then return Enum[value.e][v] end
    if t=='CFrame' then return CFrame.new(table.unpack(v)) end
    if t=='Vector3' then return Vector3.new(table.unpack(v)) end
    if t=='Vector2' then return Vector2.new(table.unpack(v)) end
    if t=='Color3' then return Color3.new(table.unpack(v)) end
    if t=='NumberRange' then return NumberRange.new(table.unpack(v)) end
    if t=='NumberSequence' then
        local k={}; for _,p in ipairs(v) do table.insert(k,NumberSequenceKeypoint.new(table.unpack(p))) end
        return NumberSequence.new(k)
    end
    if t=='ColorSequence' then
        local k={}; for _,p in ipairs(v) do table.insert(k,ColorSequenceKeypoint.new(p[1],Color3.new(p[2],p[3],p[4]))) end
        return ColorSequence.new(k)
    end
    error('Unsupported aura value '..tostring(t))
end

function VFX.ClearAura(name)
    local record=AuraObjects[name]
    if record then
        for _,obj in ipairs(record.Objects) do obj:Destroy() end
        AuraObjects[name]=nil
    end
end

function VFX.RecolorAura(name)
    local record=AuraObjects[name]
    if not record then return end
    local cfg=State.AuraConfig[name]
    local color=Color3.fromHSV(cfg.Hue/360,cfg.Saturation/100,cfg.Brightness/100)
    for obj,original in pairs(record.Colors) do
        if obj.Parent then
            obj.Color=cfg.Tint and (typeof(original)=='ColorSequence' and ColorSequence.new(color) or color) or original
        end
    end
end

function VFX.ToggleAura(name, enabled, targetCharacter)
    assert(AurasDB[name], 'Unknown aura '..tostring(name))
    enabled=enabled==true
    State.Auras[name]=enabled
    VFX.ClearAura(name)
    if not enabled or State.Unloaded then return end
    local char=targetCharacter or LocalPlayer.Character
    if not char or not char:FindFirstChild('HumanoidRootPart') then return end
    local items=AurasDB[name]
    local record={Objects={},Colors={},Character=char}
    AuraObjects[name]=record
    local ok,err=pcall(function()
        -- Allocate before resolving any references: repeated names are safe.
        for i,item in ipairs(items) do
            local obj=Instance.new(item.ClassName)
            record.Objects[i]=obj
            obj.Name=item.Name
            obj:SetAttribute('StandaloneVFX_Owner',name)
        end
        for i,item in ipairs(items) do
            local obj=record.Objects[i]
            for property,value in pairs(item.Properties) do
                obj[property]=decodeAuraValue(value,record.Objects)
            end
            if obj:IsA('ParticleEmitter') or obj:IsA('Beam') or obj:IsA('Trail') or obj:IsA('Light') then
                record.Colors[obj]=obj.Color
            end
        end
        for i,item in ipairs(items) do
            local parent=item.ParentId and record.Objects[item.ParentId] or resolveCharPart(char,item.BodyPart)
            assert(parent, 'Missing character part '..item.BodyPart)
            local obj=record.Objects[i]
            if not item.ParentId and obj:IsA('Attachment') and parent.Name~=item.BodyPart then
                if item.BodyPart=='Torso' and parent.Name=='UpperTorso' then
                    obj.CFrame=CFrame.new(0,-0.7,0)*obj.CFrame
                elseif item.BodyPart=='UpperTorso' and parent.Name=='Torso' then
                    obj.CFrame=CFrame.new(0,0.7,0)*obj.CFrame
                elseif item.BodyPart=='LowerTorso' and parent.Name=='Torso' then
                    obj.CFrame=CFrame.new(0,-0.5,0)*obj.CFrame
                end
            end
            obj.Parent=parent
        end
        VFX.RecolorAura(name)
    end)
    if not ok then
        VFX.ClearAura(name)
        State.Auras[name]=false
        local control=State.UIElements['Aura_'..name:gsub('%s+','')]
        if control then control:Set(false,false) end
        warn('[Visuals] '..name..': '..tostring(err))
        ShowNotification('Aura', 'Не удалось создать '..name, 4)
        return false,err
    end
    return true
end

TrackConnection(LocalPlayer.CharacterRemoving:Connect(function()
    for name in pairs(AuraObjects) do VFX.ClearAura(name) end
end))
TrackConnection(LocalPlayer.CharacterAdded:Connect(function(char)
    local root=char:WaitForChild('HumanoidRootPart',10)
    if not root or State.Unloaded or LocalPlayer.Character~=char then return end
    -- The rig's body parts can arrive after its root.
    local humanoid=char:WaitForChild('Humanoid',10)
    if not humanoid then return end
    char:WaitForChild(humanoid.RigType==Enum.HumanoidRigType.R6 and 'Torso' or 'UpperTorso',10)
    if State.Unloaded or LocalPlayer.Character~=char then return end
    for name,on in pairs(State.Auras) do if on then VFX.ToggleAura(name,true,char) end end
end))



