    State.ShaderPack.Bloom = on
    if State.ShaderPack.Enabled then
        local b = Lighting:FindFirstChild("Visuals_Bloom")
        if b then
            b.Enabled = on
        elseif on then
            b = VFX.GetBloom()
            b.Intensity = State.ShaderPack.BloomIntensity / 10
            b.Size = State.ShaderPack.BloomSize
            b.Threshold = 0.8
            b.Enabled = true
        end
    end
end
