-- Обработчики десяти аур: переключатель и индивидуальный HSV
for _, auraName in ipairs(AurasListNames) do
    local clean = auraName:gsub("%s+", ""):gsub("%(", ""):gsub("%)", "")

    Handlers["Aura_" .. clean] = function(on)
        VFX.ToggleAura(auraName, on)
    end

    Handlers["AuraColor_" .. clean] = function(h)
        State.AuraConfig[auraName].Hue = h
        local cfg = State.AuraConfig[auraName]
        cfg.Tint = cfg.Hue ~= 0 or cfg.Saturation ~= 90 or cfg.Brightness ~= 100
        if State.Auras[auraName] then VFX.RecolorAura(auraName) end
    end

    Handlers["AuraSat_" .. clean] = function(s)
        State.AuraConfig[auraName].Saturation = s
        local cfg = State.AuraConfig[auraName]
        cfg.Tint = cfg.Hue ~= 0 or cfg.Saturation ~= 90 or cfg.Brightness ~= 100
        if State.Auras[auraName] then VFX.RecolorAura(auraName) end
    end

    Handlers["AuraBri_" .. clean] = function(b)
        State.AuraConfig[auraName].Brightness = b
        local cfg = State.AuraConfig[auraName]
        cfg.Tint = cfg.Hue ~= 0 or cfg.Saturation ~= 90 or cfg.Brightness ~= 100
        if State.Auras[auraName] then VFX.RecolorAura(auraName) end
    end
end

